// Each star has independent position, speed and phase; the animation stays subtle.
const stars=document.createElement('div');stars.className='space-stars';stars.setAttribute('aria-hidden','true');
for(let i=0;i<70;i++){const star=document.createElement('span');star.style.left=`${Math.random()*100}%`;star.style.top=`${Math.random()*100}%`;star.style.setProperty('--twinkle-duration',`${5+Math.random()*10}s`);star.style.setProperty('--twinkle-delay',`${-Math.random()*15}s`);star.style.setProperty('--star-opacity',String(.35+Math.random()*.3));star.style.width=star.style.height=`${1+Math.random()*1.5}px`;stars.append(star);}$('sessionView').prepend(stars);
let chimeContext=null;const activeChimes=new Set();
function unlockChimes(){if(!$('chimes').checked)return;try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;chimeContext??=new Audio();if(chimeContext.state==='suspended')chimeContext.resume().catch(()=>{});}catch{}}
document.addEventListener('pointerdown',unlockChimes);document.addEventListener('keydown',unlockChimes);
playPromptChime=count=>{if(!$('chimes').checked)return;unlockChimes();if(!chimeContext||chimeContext.state!=='running')return;for(let i=0;i<count;i++){const start=chimeContext.currentTime+.03+i*.5;for(const [frequency,volume] of [[880,.10],[1320,.025]]){const oscillator=chimeContext.createOscillator(),gain=chimeContext.createGain();oscillator.type='sine';oscillator.frequency.value=frequency;gain.gain.setValueAtTime(0,start);gain.gain.linearRampToValueAtTime(volume,start+.015);gain.gain.exponentialRampToValueAtTime(.0001,start+.42);oscillator.connect(gain);gain.connect(chimeContext.destination);activeChimes.add(oscillator);oscillator.onended=()=>{activeChimes.delete(oscillator);oscillator.disconnect();gain.disconnect();};oscillator.start(start);oscillator.stop(start+.45);}}};
$('chimes').addEventListener('change',()=>{if($('chimes').checked)unlockChimes();else for(const sound of activeChimes){try{sound.stop();}catch{}}});
